Object.assign(CHULETA, {
 amv:{ r:["AM a los 15 años: ciclomotores de dos o tres ruedas y cuatriciclos ligeros. El AM limitado no incluye los de dos ruedas.","Ciclomotor: hasta 50 cm³ (combustión) y 45 km/h por construcción. La matrícula empieza por C.","Seguro obligatorio. ITV a los 3 años y luego cada 2.","Primer permiso = 8 puntos y tasa de novel (0,15 mg/l en aire) durante 2 años.","Examen teórico: 20 preguntas, máximo 2 fallos. Práctico: maniobras en pista."],
  t:["Confundir 50 (cilindrada) con 45 (velocidad).","Pensar que los ciclomotores no pasan ITV."] },
 amc:{ r:["Prohibido en autopistas y autovías.","Fuera de poblado, por el arcén derecho si es transitable. En fila: ir en paralelo es solo cosa de bicicletas.","Girar a la izquierda en interurbana sin carril especial: espera a la derecha, fuera de la calzada si puedes, y cruza cuando sea seguro.","Máximo 45 km/h en cualquier vía.","Prohibido agarrarse a otros vehículos o ir sobre una rueda.","Desde 1-10-2026: calzado cerrado siempre; guantes en interurbanas. Casco homologado obligatorio desde 1-10-2027."],
  t:["Creer que puedes ir en paralelo como las bicis.","Pensar que el arcén es opcional fuera de poblado."] },
 ams:{ r:["Los menores de 18 pueden llevar pasajero desde 2016, si el ciclomotor está homologado para dos plazas.","Pasajero: 12 años como norma; desde 7 solo con padre, madre, tutor o adulto autorizado.","Pasajero detrás, a horcajadas, con los pies en los reposapiés y con casco.","Casco abrochado siempre; sin casco: 200 € y 4 puntos.","Frena con los dos frenos de forma progresiva. Con lluvia, cuidado con pinturas y metales.","Riders: casco y chaleco siempre."],
  t:["La prohibición antigua de pasajero para menores de 18.","Casco puesto pero desabrochado."] },
 mop:{ r:["A1 (16 años): 125 cm³, 11 kW, 0,1 kW/kg. A2 (18): 35 kW, 0,2 kW/kg y origen de no más de 70 kW.","A: 2 años de A2 + curso de 9 horas (3 teoría, 6 práctica). Sin examen.","Con el B o el común aprobado, para A1 o A2 solo te queda el específico de moto: 20 preguntas, máximo 2 fallos.","Con 3 años de B: motos de 125 cm³ y 11 kW, solo en España.","ITV de moto: 4 años y luego cada 2."],
  t:["Creer que el A llega solo a los 2 años de A2.","Limitar a 35 kW una moto de más de 70 kW de origen."] },
 mot:{ r:["Contramanillar: a velocidad, empuja el lado del manillar hacia el que quieres girar.","Mira a la salida de la curva.","Frena y elige marcha antes de la curva, con la moto recta.","Postura relajada, brazos flexionados, rodillas al depósito.","En grupo, en zigzag."],
  t:["Girar el manillar como en una bici a paso de peatón.","Cambiar de marcha en plena curva."] },
 mof:{ r:["El delantero es el que más frena; usa siempre los dos, progresivos.","En curva, endereza antes de frenar fuerte.","Con ABS, a fondo y mantener.","Con lluvia, más distancia y cuidado con pinturas y tapas metálicas.","Presión en frío y ajustada a la carga. Cadena tensa y engrasada según el fabricante."],
  t:["Frenar solo con el trasero.","Frenar fuerte inclinado."] },
 moe:{ r:["Desde 1-10-2026: guantes en interurbanas y calzado cerrado siempre, conductor y pasajero.","Pasajero: 12 años, o 7 con padre, madre, tutor o adulto autorizado. Nunca entre el conductor y el manillar.","Casco integral homologado, de tu talla y abrochado. Tras un golpe fuerte, a la basura.","Ropa clara o reflectante.","Con pasajero, más distancia de frenado."],
  t:["Ir con sandalias por ciudad.","Seguir con un casco golpeado."] },
 moc:{ r:["Arcén en retenciones: solo si está señalizado y a 30 km/h como máximo.","Si no ves los espejos del camión, no te ve.","El coche que gira a la izquierda delante de ti: cuenta con que no te ha visto.","Límites como el turismo: 120, 90 y los urbanos.","Al adelantar ciclistas: −20 km/h y 1,5 m, como todos."],
  t:["Pensar que la moto puede pasar más cerca del ciclista.","Confiar en la prioridad."] },
 pro:{ r:["CAP obligatorio para trabajar con camión o autobús: inicial de 280 h (ordinario) o 140 h (acelerado); continua de 35 h cada 5 años.","Alcohol profesional: 0,15 mg/l en aire o 0,3 g/l en sangre.","Permisos C1, C, D1 y D: vigencia de 5 años (3 desde los 65).","ADR para mercancías peligrosas: autorización aparte; exige B con más de 1 año."],
  t:["Creer que el CAP sustituye al permiso.","Aplicar la tasa general de 0,25."] },
 tie:{ r:["Conducción diaria: 9 h (10 h dos veces por semana).","Pausa: 45 min tras 4 h 30, o 15 + 30 en ese orden.","Semana: 56 h. Dos semanas seguidas: 90 h.","Descanso diario: 11 h (3 + 9), reducible a 9 h tres veces entre descansos semanales.","Descanso semanal: 45 h, reducible a 24 h compensando.","Se aplica a mercancías de más de 3,5 t y a viajeros de más de 9 plazas con el conductor; fuera quedan las líneas regulares de hasta 50 km.","Tarjeta de conductor personal. El tacógrafo registra conducción, otros trabajos, disponibilidad y descanso."],
  t:["Fraccionar la pausa en 30 + 15.","Confundir 56 h de conducción con 48 h de trabajo."] },
 cpe:{ r:["C1: de 3.500 a 7.500 kg (18 años). C: más de 3.500 kg (21, o 18 con CAP ordinario). Ninguno sirve para autobuses.","Los dos exigen el B y permiten remolques de hasta 750 kg; más, con la E.","Velocidad del camión: 90 autopista y autovía, 80 convencional; mercancías peligrosas, 10 menos.","Panel naranja = mercancías peligrosas.","Examen específico: 20 preguntas, máximo 2 fallos."],
  t:["Usar el 90 del turismo en convencional.","Creer que el C exige antes el C1."] },
 dim:{ r:["Altura 4 m. Anchura 2,55 m (2,60 frigoríficos).","Longitud: rígido 12 m · articulado 16,50 m · tren de carretera 18,75 m.","Carga indivisible: vehículo de más de 5 m, 2 m delante y 3 m detrás; de 5 m o menos, un tercio por cada extremo; lateral, 0,40 m por lado sin pasar de 2,55 m.","Carga sobresaliente detrás: panel V-20; de noche, luz roja detrás y blanca delante.","Carga repartida, lo pesado abajo y trincada. Tara = masa en vacío."],
  t:["Invertir el 2 y el 3 de la carga sobresaliente.","Confundir 16,50 (articulado) con 18,75 (tren)."] },
 fre:{ r:["Bajadas largas: marcha corta y ralentizador; frenar todo el rato produce fading.","Testigo de baja presión de aire: detente en lugar seguro.","Purga los calderines para eliminar el agua.","Limitador obligatorio a 90 km/h en camiones de más de 3.500 kg.","Revisión antes de salir: neumáticos, luces, frenos, niveles y carga."],
  t:["Bajar puertos con el freno de servicio.","Seguir con el testigo de aire encendido."] },
 cpc:{ r:["Fuera de poblado, en vías de un carril por sentido y sin intención de adelantar: 50 m con el de delante (más de 3.500 kg o más de 10 m).","Túnel: 150 m o 6 s.","Ángulo muerto: lateral derecho y delante de la cabina. Antes de girar a la derecha, espejos.","Vacío y con lonas, el viento puede desviarlo o volcarlo.","Al adelantar ciclistas: −20 km/h y 1,5 m, y más por el rebufo."],
  t:["Creer que los 50 m se aplican en todas las vías.","Girar a la derecha sin mirar el espejo."] },
 dpe:{ r:["D1: hasta 16 plazas + conductor y 8 m (21 años, o 18 con CAP, solo en España hasta los 21). D: más de 8 plazas + conductor (24 años, con excepciones por CAP).","Los dos exigen el B y permiten remolque de hasta 750 kg.","Velocidad: 100 autopista y autovía, 90 convencional. Escolar: 10 menos. Con viajeros de pie o sin cinturones: 80 fuera de poblado.","Examen específico: 20 preguntas, máximo 2 fallos."],
  t:["Usar el 90/80 del camión para el autobús.","Olvidar el límite de 80 con viajeros de pie."] },
 dpa:{ r:["Cinturón obligatorio para los viajeros si el asiento lo tiene; la empresa o el conductor deben informarlo.","Con viajeros de pie, todo suave.","Puertas solo con el autobús parado.","Martillos rompecristales y extintor accesibles. Incendio: detener, abrir, evacuar, 112.","Silla de ruedas en su espacio y sujeta. Equipaje sin tapar salidas ni pasillos.","Escolares: vigilar subida y bajada antes de arrancar."],
  t:["Pensar que en autobús no hay que usar cinturón.","Abrir las puertas antes de parar."] },
 dci:{ r:["En poblado hay que facilitar la incorporación del autobús que sale de su parada, pero no tiene prioridad absoluta.","50 m fuera de poblado en vías de un carril por sentido; 150 m o 6 s en túnel.","Longitud: rígido de dos ejes 13,50 m; articulado 18,75 m.","En la parada, arrimado al bordillo."],
  t:["Creer que el autobús tiene prioridad absoluta al salir."] },
 rpe:{ r:["Remolque ligero: hasta 750 kg; va con la matrícula y el seguro del tractor. Más de 750 kg: matrícula, permiso de circulación e ITV propios.","B+E: remolque de hasta 3.500 kg (18 años, con B). El código 96 del B permite conjuntos de hasta 4.250 kg.","C1+E: conjunto hasta 12.000 kg. C+E exige el C; D+E exige el D.","C1+E, C+E, D1+E y D+E autorizan también B+E.","Examen específico: 20 preguntas, máximo 2 fallos."],
  t:["Confundir el código 96 con el B+E.","Creer que el remolque ligero necesita matrícula propia."] },
 rac:{ r:["Más de 750 kg: frenos propios obligatorios; el freno de inercia actúa cuando el remolque empuja.","Cable de ruptura: frena el remolque si se suelta.","Bola homologada y legalizada en la ITV.","Acoplar: enganchar, comprobar cierre, conectar cables, subir rueda jockey, comprobar luces.","Semirremolque: pivote bloqueado en la quinta rueda; manguera roja alimentación, amarilla servicio."],
  t:["Invertir los colores de las mangueras.","Salir sin comprobar las luces."] },
 rca:{ r:["Carga repartida, lo pesado abajo y cerca del eje.","Carga vertical en la bola según el fabricante: ni mucha ni nada.","Serpenteo: pie fuera del acelerador, volante firme y frenada suave si hace falta.","No superar la masa remolcable de la ficha técnica.","Nadie dentro del remolque. Retrovisores adicionales si el remolque tapa la vista."],
  t:["Acelerar para corregir el serpenteo.","Cargar lo pesado al fondo."] },
 rci:{ r:["Con remolque: 90 autopista y autovía, 80 convencional.","Nadie supera el límite para adelantar.","Marcha atrás: volante al lado contrario de donde quieres llevar el remolque.","Más distancia de frenado y más espacio para adelantar.","Conjunto de más de 10 m: 50 m en vías de un carril por sentido.","En curvas cerradas el remolque recorta por dentro."],
  t:["Girar el volante hacia donde quieres que vaya el remolque.","Adelantar como si fuera solo el coche."] }
});

